  "components": [
    {
      "name": "Web front end",
      "responsibility": "Shows the catalogue, the item, the checkout and the confirmation pages.",
      "dependsOn": [
        "Shop service"
      ]
    },
    {
      "name": "Shop service",
      "responsibility": "Finds items, keeps the basket and places orders.",
      "dependsOn": [
        "Database"
      ]
    },
    {
      "name": "Database",
      "responsibility": "Keeps the catalogue items and the basket lines.",
      "dependsOn": []
    }
  ],
  "decisions": [
    {
      "title": "Keep the shop rules in one service",
      "context": "The shipping fee sits in the order service of the legacy shop.",
      "decision": "The shop service owns the search, the basket and the shipping fee.",
      "consequences": "Pages call the service and hold no rule.",
      "sources": [
        "BR-001"
      ]
    }
  ],
  "entities": [
    {
      "legacy": "Catalog item",
      "target": "catalog_item",
      "notes": "The price keeps two decimals.",
      "sources": [
        "ENT-001"
      ]
    },
    {
      "legacy": "Basket line",
      "target": "basket_line",
      "notes": "The basket is held in the session today; the new line belongs to a stored basket.",
      "sources": [
        "ENT-002"
      ]
    }
  ],
  "phases": [
    {
      "name": "Catalogue and basket",
      "goal": "Visitors browse and fill a basket on the new system.",
      "exitCriteria": [
        "A visitor finds an item and adds it to the basket on the new system."
      ]
    },
    {
      "name": "Orders",
      "goal": "Orders are placed on the new system.",
      "exitCriteria": [
        "Every order is placed on the new system with the same shipping fee."
      ]
    }
  ],
  "tasks": [
    {
      "title": "Catalogue search and basket",
      "phase": 1,
      "requirements": [
        1,
        2
      ],
      "acceptanceCriteria": [
        "Given the term \"lamp\", when a visitor searches, then the items whose name holds lamp are listed.",
        "Given a quantity of 11, when a visitor adds an item, then the basket is unchanged and the page shows an error."
      ],
      "invariant": "A basket line always names one catalogue item and a whole quantity from 1 to 10, however the quantity is written.",
      "riskClass": "data loss",
      "adds": [
        "limit"
      ],
      "probes": [
        "A quantity of 0, 1, 10 and 11.",
        "A quantity written 1.0, 01 and 1e1.",
        "An item id that is not in the catalogue."
      ],
      "files": [
        "src/catalogue/",
        "src/basket/",
        "tests/basket/"
      ],
      "needs": [
        {
          "kind": "error code",
          "purpose": "quantity outside 1 to 10"
        }
      ]
    },
    {
      "title": "Checkout and order placement",
      "phase": 2,
      "requirements": [
        3,
        4
      ],
      "acceptanceCriteria": [
        "Given a basket and the shipping choice express, when the visitor places the order, then the fee is 12.",
        "Given a basket and any other shipping choice, when the visitor places the order, then the fee is 4."
      ],
      "invariant": "The shipping fee is 12 exactly when the choice is express, whatever its letter case.",
      "riskClass": "money",
      "adds": [
        "check"
      ],
      "probes": [
        "The choices express, Express and EXPRESS and \"express \" with a trailing space.",
        "A blank, an unknown and a missing shipping choice.",
        "An e-mail address with no at sign, with two at signs and with a blank name."
      ],
      "files": [
        "src/orders/",
        "tests/orders/"
      ],
      "needs": [
        {
          "kind": "error code",
          "purpose": "malformed e-mail address"
        }
      ],
      "dependsOn": [
        1
      ]
    }
  ],
  "risks": [
    {
      "text": "The legacy checkout does not return after the redirect for a visitor without a basket, so an empty order may be placed today.",
      "sources": [
        "OQ-001"
      ]
    }
  ]
}
